using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, JsonOptions);
    }

    [McpServerResource(
        UriTemplate = "config://app/status",
        Name = "Service Status",
        MimeType = "application/json"),
     Description("Returns the current service health status.")]
    public static string GetServiceStatus()
    {
        var status = new
        {
            Status = "Healthy",
            Uptime = Environment.TickCount64 / 1000,
            Timestamp = DateTimeOffset.UtcNow
        };

        return JsonSerializer.Serialize(status, JsonOptions);
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class EchoTools
{
    [McpServerTool, Description("Echoes the provided message back, optionally in uppercase.")]
    public static string Echo(
        [Description("The message to echo")] string message,
        [Description("Whether to convert the message to uppercase")] bool uppercase = false)
    {
        return uppercase ? message.ToUpperInvariant() : message;
    }

    [McpServerTool, Description("Returns the current server UTC date and time.")]
    public static string GetServerTime()
    {
        return DateTimeOffset.UtcNow.ToString("o");
    }
}

